{
    // To avoid bias, we need to make the range of the RNG a multiple of
    // bound, which we do by dropping output less than a threshold.
    // A naive scheme to calculate the threshold would be to do
    //
    //     uint32_t threshold = 0x100000000ull % bound;
    //
    // but 64-bit div/mod is slower than 32-bit div/mod (especially on
    // 32-bit platforms).  In essence, we do
    //
    //     uint32_t threshold = (0x100000000ull-bound) % bound;
    //
    // because this version will calculate the same modulus, but the LHS
    // value is less than 2^32.

    uint32_t threshold = -bound % bound;

    // Uniformity guarantees that this loop will terminate.  In practice, it
    // should usually terminate quickly; on average (assuming all bounds are
    // equally likely), 82.25% of the time, we can expect it to require just
    // one iteration.  In the worst case, someone passes a bound of 2^31 + 1
    // (i.e., 2147483649), which invalidates almost 50% of the range.  In 
    // practice, bounds are typically small and only a tiny amount of the range
    // is eliminated.
    for (;;) {
        uint32_t r = pcg32_random_r(rng);
        if (r >= threshold)
            return r % bound;
    }
}

uint32_t pcg32_boundedrand(uint32_t bound)
{
    return pcg32_boundedrand_r(&pcg32_global, bound);
}

double genann_act_hidden_indirect(const struct genann *ann, double a) {
    return ann->activation_hidden(ann, a);
}

double genann_act_output_indirect(const struct genann *ann, double a) {
    return ann->activation_output(ann, a);
}

double genann_act_sigmoid(const genann *ann unused, double a) {
    if (a < -45.0) return 0;
    if (a > 45.0) return 1;
    return 1.0 / (1 + exp(-a));
}

void genann_init_sigmoid_lookup(const genann *ann) {
        const double f = (sigmoid_dom_max - sigmoid_dom_min) / LOOKUP_SIZE;
        int i;

        interval = LOOKUP_SIZE / (sigmoid_dom_max - sigmoid_dom_min);
        for (i = 0; i < LOOKUP_SIZE; ++i) {
            lookup[i] = genann_act_sigmoid(ann, sigmoid_dom_min + f * i);
        }
}

double genann_act_sigmoid_cached(const genann *ann unused, double a) {
    assert(!isnan(a));

    if (a < sigmoid_dom_min) return lookup[0];
    if (a >= sigmoid_dom_max) return lookup[LOOKUP_SIZE - 1];

    size_t j = (size_t)((a-sigmoid_dom_min)*interval+0.5);

    /* Because floating point... */
    if (unlikely(j >= LOOKUP_SIZE)) return lookup[LOOKUP_SIZE - 1];

    return lookup[j];
}

double genann_act_linear(const struct genann *ann unused, double a) {
    return a;
}

double genann_act_threshold(const struct genann *ann unused, double a) {
    return a > 0;
}

genann *genann_init(int inputs, int hidden_layers, int hidden, int outputs) {
    if (hidden_layers < 0) return 0;
    if (inputs < 1) return 0;
    if (outputs < 1) return 0;
    if (hidden_layers > 0 && hidden < 1) return 0;


    const int hidden_weights = hidden_layers ? (inputs+1) * hidden + (hidden_layers-1) * (hidden+1) * hidden : 0;
    const int output_weights = (hidden_layers ? (hidden+1) : (inputs+1)) * outputs;
    const int total_weights = (hidden_weights + output_weights);

    const int total_neurons = (inputs + hidden * hidden_layers + outputs);

    /* Allocate extra size for weights, outputs, and deltas. */
    const int size = sizeof(genann) + sizeof(double) * (total_weights + total_neurons + (total_neurons - inputs));
    genann *ret = malloc(size);
    if (!ret) return 0;

    ret->inputs = inputs;
    ret->hidden_layers = hidden_layers;
    ret->hidden = hidden;
    ret->outputs = outputs;

    ret->total_weights = total_weights;
    ret->total_neurons = total_neurons;

    /* Set pointers. */
    ret->weight = (double*)((char*)ret + sizeof(genann));
    ret->output = ret->weight + ret->total_weights;
    ret->delta = ret->output + ret->total_neurons;

    genann_randomize(ret);

    ret->activation_hidden = genann_act_sigmoid_cached;
    ret->activation_output = genann_act_sigmoid_cached;

    genann_init_sigmoid_lookup(ret);

    return ret;
}

void genann_randomize(genann *ann) {
    int i;
    for (i = 0; i < ann->total_weights; ++i) {
        double r = GENANN_RANDOM();
        /* Sets weights from -0.5 to 0.5. */
        ann->weight[i] = r - 0.5;
    }
}

void genann_free(genann *ann) {
    /* The weight, output, and delta pointers go to the same buffer. */
    free(ann);
}

double const *genann_run(genann const *ann, double const *inputs) {
    double const *w = ann->weight;
    double *o = ann->output + ann->inputs;
    double const *i = ann->output;

    /* Copy the inputs to the scratch area, where we also store each neuron's
     * output, for consistency. This way the first layer isn't a special case. */
    memcpy(ann->output, inputs, sizeof(double) * ann->inputs);

    int h, j, k;

    if (!ann->hidden_layers) {
        double *ret = o;
        for (j = 0; j < ann->outputs; ++j) {
            double sum = *w++ * -1.0;
            for (k = 0; k < ann->inputs; ++k) {
                sum += *w++ * i[k];
            }
            *o++ = genann_act_output(ann, sum);
        }

        return ret;
    }

    /* Figure input layer */
    for (j = 0; j < ann->hidden; ++j) {
        double sum = *w++ * -1.0;
        for (k = 0; k < ann->inputs; ++k) {
            sum += *w++ * i[k];
        }
        *o++ = genann_act_hidden(ann, sum);
    }

    i += ann->inputs;

    /* Figure hidden layers, if any. */
    for (h = 1; h < ann->hidden_layers; ++h) {
        for (j = 0; j < ann->hidden; ++j) {
            double sum = *w++ * -1.0;
            for (k = 0; k < ann->hidden; ++k) {
                sum += *w++ * i[k];
            }
            *o++ = genann_act_hidden(ann, sum);
        }

        i += ann->hidden;
    }

    double const *ret = o;

    /* Figure output layer. */
    for (j = 0; j < ann->outputs; ++j) {
        double sum = *w++ * -1.0;
        for (k = 0; k < ann->hidden; ++k) {
            sum += *w++ * i[k];
        }
        *o++ = genann_act_output(ann, sum);
    }

    /* Sanity check that we used all weights and wrote all outputs. */
    assert(w - ann->weight == ann->total_weights);
    assert(o - ann->output == ann->total_neurons);

    return ret;
}

void genann_train(genann const *ann, double const *inputs, double const *desired_outputs, double learning_rate) {
    /* To begin with, we must run the network forward. */
    genann_run(ann, inputs);

    int h, j, k;

    /* First set the output layer deltas. */
    {
        double const *o = ann->output + ann->inputs + ann->hidden * ann->hidden_layers; /* First output. */
        double *d = ann->delta + ann->hidden * ann->hidden_layers; /* First delta. */
        double const *t = desired_outputs; /* First desired output. */


        /* Set output layer deltas. */
        if (genann_act_output == genann_act_linear ||
                ann->activation_output == genann_act_linear) {
            for (j = 0; j < ann->outputs; ++j) {
                *d++ = *t++ - *o++;
            }
        } else {
            for (j = 0; j < ann->outputs; ++j) {
                *d++ = (*t - *o) * *o * (1.0 - *o);
                ++o; ++t;
            }
        }
    }


    /* Set hidden layer deltas, start on last layer and work backwards. */
    /* Note that loop is skipped in the case of hidden_layers == 0. */
    for (h = ann->hidden_layers - 1; h >= 0; --h) {

        /* Find first output and delta in this layer. */
        double const *o = ann->output + ann->inputs + (h * ann->hidden);
        double *d = ann->delta + (h * ann->hidden);

        /* Find first delta in following layer (which may be hidden or output). */
        double const * const dd = ann->delta + ((h+1) * ann->hidden);

        /* Find first weight in following layer (which may be hidden or output). */
        double const * const ww = ann->weight + ((ann->inputs+1) * ann->hidden) + ((ann->hidden+1) * ann->hidden * (h));

        for (j = 0; j < ann->hidden; ++j) {

            double delta = 0;

            for (k = 0; k < (h == ann->hidden_layers-1 ? ann->outputs : ann->hidden); ++k) {
                const double forward_delta = dd[k];
                const int windex = k * (ann->hidden + 1) + (j + 1);
                const double forward_weight = ww[windex];
                delta += forward_delta * forward_weight;
            }

            *d = *o * (1.0-*o) * delta;
            ++d; ++o;
        }
    }


    /* Train the outputs. */
    {
        /* Find first output delta. */
        double const *d = ann->delta + ann->hidden * ann->hidden_layers; /* First output delta. */

        /* Find first weight to first output delta. */
        double *w = ann->weight + (ann->hidden_layers
                ? ((ann->inputs+1) * ann->hidden + (ann->hidden+1) * ann->hidden * (ann->hidden_layers-1))
                : (0));

        /* Find first output in previous layer. */
        double const * const i = ann->output + (ann->hidden_layers
                ? (ann->inputs + (ann->hidden) * (ann->hidden_layers-1))
                : 0);

        /* Set output layer weights. */
        for (j = 0; j < ann->outputs; ++j) {
            *w++ += *d * learning_rate * -1.0;
            for (k = 1; k < (ann->hidden_layers ? ann->hidden : ann->inputs) + 1; ++k) {
                *w++ += *d * learning_rate * i[k-1];
            }

            ++d;
        }

        assert(w - ann->weight == ann->total_weights);
    }


    /* Train the hidden layers. */
    for (h = ann->hidden_layers - 1; h >= 0; --h) {

        /* Find first delta in this layer. */
        double const *d = ann->delta + (h * ann->hidden);

        /* Find first input to this layer. */
        double const *i = ann->output + (h
                ? (ann->inputs + ann->hidden * (h-1))
                : 0);

        /* Find first weight to this layer. */
        double *w = ann->weight + (h
                ? ((ann->inputs+1) * ann->hidden + (ann->hidden+1) * (ann->hidden) * (h-1))
                : 0);


        for (j = 0; j < ann->hidden; ++j) {
            *w++ += *d * learning_rate * -1.0;
            for (k = 1; k < (h == 0 ? ann->inputs : ann->hidden) + 1; ++k) {
                *w++ += *d * learning_rate * i[k-1];
            }
            ++d;
        }

    }

}

int phr_parse_request(const char *buf_start, size_t len, const char **method, size_t *method_len, const char **path,
                      size_t *path_len, int *minor_version, struct phr_header *headers, size_t *num_headers, size_t last_len)
{
    const char *buf = buf_start, *buf_end = buf_start + len;
    size_t max_headers = *num_headers;
    int r;

    *method = NULL;
    *method_len = 0;
    *path = NULL;
    *path_len = 0;
    *minor_version = -1;
    *num_headers = 0;

    /* if last_len != 0, check if the request is complete (a fast countermeasure
       againt slowloris */
    if (last_len != 0 && is_complete(buf, buf_end, last_len, &r) == NULL) {
        return r;
    }

    if ((buf = parse_request(buf, buf_end, method, method_len, path, path_len, minor_version, headers, num_headers, max_headers,
                             &r)) == NULL) {
        return r;
    }

    return (int)(buf - buf_start);
}

int phr_parse_response(const char *buf_start, size_t len, int *minor_version, int *status, const char **msg, size_t *msg_len,
                       struct phr_header *headers, size_t *num_headers, size_t last_len)
{
    const char *buf = buf_start, *buf_end = buf + len;
    size_t max_headers = *num_headers;
    int r;

    *minor_version = -1;
    *status = 0;
    *msg = NULL;
    *msg_len = 0;
    *num_headers = 0;

    /* if last_len != 0, check if the response is complete (a fast countermeasure
       against slowloris */
    if (last_len != 0 && is_complete(buf, buf_end, last_len, &r) == NULL) {
        return r;
    }

    if ((buf = parse_response(buf, buf_end, minor_version, status, msg, msg_len, headers, num_headers, max_headers, &r)) == NULL) {
        return r;
    }

    return (int)(buf - buf_start);
}

int phr_parse_headers(const char *buf_start, size_t len, struct phr_header *headers, size_t *num_headers, size_t last_len)
{
    const char *buf = buf_start, *buf_end = buf + len;
    size_t max_headers = *num_headers;
    int r;

    *num_headers = 0;

    /* if last_len != 0, check if the response is complete (a fast countermeasure
       against slowloris */
    if (last_len != 0 && is_complete(buf, buf_end, last_len, &r) == NULL) {
        return r;
    }

    if ((buf = parse_headers(buf, buf_end, headers, num_headers, max_headers, &r)) == NULL) {
        return r;
    }

    return (int)(buf - buf_start);
}

ssize_t phr_decode_chunked(struct phr_chunked_decoder *decoder, char *buf, size_t *_bufsz)
{
    size_t dst = 0, src = 0, bufsz = *_bufsz;
    ssize_t ret = -2; /* incomplete */

    decoder->_total_read += bufsz;

    while (1) {
        switch (decoder->_state) {
        case CHUNKED_IN_CHUNK_SIZE:
            for (;; ++src) {
                int v;
                if (src == bufsz)
                    goto Exit;
                if ((v = decode_hex(buf[src])) == -1) {
                    if (decoder->_hex_count == 0) {
                        ret = -1;
                        goto Exit;
                    }
                    /* the only characters that may appear after the chunk size are BWS, semicolon, or CRLF */
                    switch (buf[src]) {
                    case ' ':
                    case '\011':
                    case ';':
                    case '\012':
                    case '\015':
                        break;
                    default:
                        ret = -1;
                        goto Exit;
                    }
                    break;
                }
                if (decoder->_hex_count == sizeof(size_t) * 2) {
                    ret = -1;
                    goto Exit;
                }
                decoder->bytes_left_in_chunk = decoder->bytes_left_in_chunk * 16 + v;
                ++decoder->_hex_count;
            }
            decoder->_hex_count = 0;
            decoder->_state = CHUNKED_IN_CHUNK_EXT;
        /* fallthru */
        case CHUNKED_IN_CHUNK_EXT:
            /* RFC 7230 A.2 "Line folding in chunk extensions is disallowed" */
            for (;; ++src) {
                if (src == bufsz)
                    goto Exit;
                if (buf[src] == '\015') {
                    break;
                } else if (buf[src] == '\012') {
                    ret = -1;
                    goto Exit;
                }
            }
            ++src;
            decoder->_state = CHUNKED_IN_CHUNK_HEADER_EXPECT_LF;
        /* fallthru */
        case CHUNKED_IN_CHUNK_HEADER_EXPECT_LF:
            if (src == bufsz)
                goto Exit;
            if (buf[src] != '\012') {
                ret = -1;
                goto Exit;
            }
            ++src;
            if (decoder->bytes_left_in_chunk == 0) {
                if (decoder->consume_trailer) {
                    decoder->_state = CHUNKED_IN_TRAILERS_LINE_HEAD;
                    break;
                } else {
                    goto Complete;
                }
            }
            decoder->_state = CHUNKED_IN_CHUNK_DATA;
        /* fallthru */
        case CHUNKED_IN_CHUNK_DATA: {
            size_t avail = bufsz - src;
            if (avail < decoder->bytes_left_in_chunk) {
                if (dst != src)
                    memmove(buf + dst, buf + src, avail);
                src += avail;
                dst += avail;
                decoder->bytes_left_in_chunk -= avail;
                goto Exit;
            }
            if (dst != src)
                memmove(buf + dst, buf + src, decoder->bytes_left_in_chunk);
            src += decoder->bytes_left_in_chunk;
            dst += decoder->bytes_left_in_chunk;
            decoder->bytes_left_in_chunk = 0;
            decoder->_state = CHUNKED_IN_CHUNK_DATA_EXPECT_CR;
        }
        /* fallthru */
        case CHUNKED_IN_CHUNK_DATA_EXPECT_CR:
            if (src == bufsz)
                goto Exit;
            if (buf[src] != '\015') {
                ret = -1;
                goto Exit;
            }
            ++src;
            decoder->_state = CHUNKED_IN_CHUNK_DATA_EXPECT_LF;
        /* fallthru */
        case CHUNKED_IN_CHUNK_DATA_EXPECT_LF:
            if (src == bufsz)
                goto Exit;
            if (buf[src] != '\012') {
                ret = -1;
                goto Exit;
            }
            ++src;
            decoder->_state = CHUNKED_IN_CHUNK_SIZE;
            break;
        case CHUNKED_IN_TRAILERS_LINE_HEAD:
            for (;; ++src) {
                if (src == bufsz)
                    goto Exit;
                if (buf[src] != '\015')
                    break;
            }
            if (buf[src++] == '\012')
                goto Complete;
            decoder->_state = CHUNKED_IN_TRAILERS_LINE_MIDDLE;
        /* fallthru */
        case CHUNKED_IN_TRAILERS_LINE_MIDDLE:
            for (;; ++src) {
                if (src == bufsz)
                    goto Exit;
                if (buf[src] == '\012')
                    break;
            }
            ++src;
            decoder->_state = CHUNKED_IN_TRAILERS_LINE_HEAD;
            break;
        default:
            assert(!"decoder is corrupt");
        }
    }

Complete:
    ret = bufsz - src;
Exit:
    if (dst != src)
        memmove(buf + dst, buf + src, bufsz - src);
    *_bufsz = dst;
    /* if incomplete but the overhead of the chunked encoding is >=100KB and >80%, signal an error */
    if (ret == -2) {
        decoder->_total_overhead += bufsz - dst;
        if (decoder->_total_overhead >= 100 * 1024 && decoder->_total_read - decoder->_total_overhead < decoder->_total_read / 4)
            ret = -1;
    }
    return ret;
}

int phr_decode_chunked_is_in_data(struct phr_chunked_decoder *decoder)
{
    return decoder->_state == CHUNKED_IN_CHUNK_DATA;
}

void MurmurHash3_x86_32 ( const void * key, int len,
                          uint32_t seed, void * out )
{
  const uint8_t * data = (const uint8_t*)key;
  const int nblocks = len / 4;
  int i;

  uint32_t h1 = seed;

  uint32_t c1 = 0xcc9e2d51;
  uint32_t c2 = 0x1b873593;

  const uint32_t * blocks = (const uint32_t *)(data + nblocks*4);

  for(i = -nblocks; i; i++)
  {
    uint32_t k1 = (blocks[i]);

    k1 *= c1;
    k1 = rotl32(k1,15);
    k1 *= c2;

    h1 ^= k1;
    h1 = rotl32(h1,13);
    h1 = h1*5+0xe6546b64;
  }

  const uint8_t * tail = (const uint8_t*)(data + nblocks*4);

  uint32_t k1 = 0;

  switch(len & 3)
  {
  case 3: k1 ^= tail[2] << 16;
  case 2: k1 ^= tail[1] << 8;
  case 1: k1 ^= tail[0];
          k1 *= c1; k1 = rotl32(k1,15); k1 *= c2; h1 ^= k1;
  };

  h1 ^= len;

  h1 = fmix32(h1);

  *(uint32_t*)out = h1;
}

void MurmurHash3_x86_128 ( const void * key, const int len,
                           uint32_t seed, void * out )
{
  const uint8_t * data = (const uint8_t*)key;
  const int nblocks = len / 16;
  int i;

  uint32_t h1 = seed;
  uint32_t h2 = seed;
  uint32_t h3 = seed;
  uint32_t h4 = seed;

  uint32_t c1 = 0x239b961b;
  uint32_t c2 = 0xab0e9789;
  uint32_t c3 = 0x38b34ae5;
  uint32_t c4 = 0xa1e38b93;

  const uint32_t * blocks = (const uint32_t *)(data + nblocks*16);

  for(i = -nblocks; i; i++)
  {
    uint32_t k1 = (blocks[i*4+0]);
    uint32_t k2 = (blocks[i*4+1]);
    uint32_t k3 = (blocks[i*4+2]);
    uint32_t k4 = (blocks[i*4+3]);

    k1 *= c1; k1 = rotl32(k1,15); k1 *= c2; h1 ^= k1;

    h1 = rotl32(h1,19); h1 += h2; h1 = h1*5+0x561ccd1b;

    k2 *= c2; k2 = rotl32(k2,16); k2 *= c3; h2 ^= k2;

    h2 = rotl32(h2,17); h2 += h3; h2 = h2*5+0x0bcaa747;

    k3 *= c3; k3 = rotl32(k3,17); k3 *= c4; h3 ^= k3;

    h3 = rotl32(h3,15); h3 += h4; h3 = h3*5+0x96cd1c35;

    k4 *= c4; k4 = rotl32(k4,18); k4 *= c1; h4 ^= k4;

    h4 = rotl32(h4,13); h4 += h1; h4 = h4*5+0x32ac3b17;
  }

  const uint8_t * tail = (const uint8_t*)(data + nblocks*16);

  uint32_t k1 = 0;
  uint32_t k2 = 0;
  uint32_t k3 = 0;
  uint32_t k4 = 0;

  switch(len & 15)
  {
  case 15: k4 ^= tail[14] << 16;
  case 14: k4 ^= tail[13] << 8;
  case 13: k4 ^= tail[12] << 0;
           k4 *= c4; k4 = rotl32(k4,18); k4 *= c1; h4 ^= k4;

  case 12: k3 ^= tail[11] << 24;
  case 11: k3 ^= tail[10] << 16;
  case 10: k3 ^= tail[ 9] << 8;
  case 9: k3 ^= tail[ 8] << 0;
           k3 *= c3; k3 = rotl32(k3,17); k3 *= c4; h3 ^= k3;

  case 8: k2 ^= tail[ 7] << 24;
  case 7: k2 ^= tail[ 6] << 16;
  case 6: k2 ^= tail[ 5] << 8;
  case 5: k2 ^= tail[ 4] << 0;
           k2 *= c2; k2 = rotl32(k2,16); k2 *= c3; h2 ^= k2;

  case 4: k1 ^= tail[ 3] << 24;
  case 3: k1 ^= tail[ 2] << 16;
  case 2: k1 ^= tail[ 1] << 8;
  case 1: k1 ^= tail[ 0] << 0;
           k1 *= c1; k1 = rotl32(k1,15); k1 *= c2; h1 ^= k1;
  };

  h1 ^= len; h2 ^= len; h3 ^= len; h4 ^= len;

  h1 += h2; h1 += h3; h1 += h4;
  h2 += h1; h3 += h1; h4 += h1;

  h1 = fmix32(h1);
  h2 = fmix32(h2);
  h3 = fmix32(h3);
  h4 = fmix32(h4);

  h1 += h2; h1 += h3; h1 += h4;
  h2 += h1; h3 += h1; h4 += h1;

  ((uint32_t*)out)[0] = h1;
  ((uint32_t*)out)[1] = h2;
  ((uint32_t*)out)[2] = h3;
  ((uint32_t*)out)[3] = h4;
}

void MurmurHash3_x64_128 ( const void * key, const int len,
                           const uint32_t seed, void * out )
{
  const uint8_t * data = (const uint8_t*)key;
  const int nblocks = len / 16;
  int i;

  uint64_t h1 = seed;
  uint64_t h2 = seed;

  uint64_t c1 = (0x87c37b91114253d5LLU);
  uint64_t c2 = (0x4cf5ad432745937fLLU);

  const uint64_t * blocks = (const uint64_t *)(data);

  for(i = 0; i < nblocks; i++)
  {
    uint64_t k1 = (blocks[i*2+0]);
    uint64_t k2 = (blocks[i*2+1]);

    k1 *= c1; k1 = rotl64(k1,31); k1 *= c2; h1 ^= k1;

    h1 = rotl64(h1,27); h1 += h2; h1 = h1*5+0x52dce729;

    k2 *= c2; k2 = rotl64(k2,33); k2 *= c1; h2 ^= k2;

    h2 = rotl64(h2,31); h2 += h1; h2 = h2*5+0x38495ab5;
  }

  const uint8_t * tail = (const uint8_t*)(data + nblocks*16);

  uint64_t k1 = 0;
  uint64_t k2 = 0;

  switch(len & 15)
  {
  case 15: k2 ^= (uint64_t)(tail[14]) << 48;
  case 14: k2 ^= (uint64_t)(tail[13]) << 40;
  case 13: k2 ^= (uint64_t)(tail[12]) << 32;
  case 12: k2 ^= (uint64_t)(tail[11]) << 24;
  case 11: k2 ^= (uint64_t)(tail[10]) << 16;
  case 10: k2 ^= (uint64_t)(tail[ 9]) << 8;
  case 9: k2 ^= (uint64_t)(tail[ 8]) << 0;
           k2 *= c2; k2 = rotl64(k2,33); k2 *= c1; h2 ^= k2;

  case 8: k1 ^= (uint64_t)(tail[ 7]) << 56;
  case 7: k1 ^= (uint64_t)(tail[ 6]) << 48;
  case 6: k1 ^= (uint64_t)(tail[ 5]) << 40;
  case 5: k1 ^= (uint64_t)(tail[ 4]) << 32;
  case 4: k1 ^= (uint64_t)(tail[ 3]) << 24;
  case 3: k1 ^= (uint64_t)(tail[ 2]) << 16;
  case 2: k1 ^= (uint64_t)(tail[ 1]) << 8;
  case 1: k1 ^= (uint64_t)(tail[ 0]) << 0;
           k1 *= c1; k1 = rotl64(k1,31); k1 *= c2; h1 ^= k1;
  };

  h1 ^= len; h2 ^= len;

  h1 += h2;
  h2 += h1;

  h1 = fmix64(h1);
  h2 = fmix64(h2);

  h1 += h2;
  h2 += h1;

  ((uint64_t*)out)[0] = h1;
  ((uint64_t*)out)[1] = h2;
}

void sha_256_init(struct Sha_256 *sha_256, uint8_t hash[32])
{
 sha_256->hash = hash;
 sha_256->chunk_pos = sha_256->chunk;
 sha_256->space_left = 64;
 sha_256->total_len = 0;

 sha_256->h[0] = 0x6a09e667;
 sha_256->h[1] = 0xbb67ae85;
 sha_256->h[2] = 0x3c6ef372;
 sha_256->h[3] = 0xa54ff53a;
 sha_256->h[4] = 0x510e527f;
 sha_256->h[5] = 0x9b05688c;
 sha_256->h[6] = 0x1f83d9ab;
 sha_256->h[7] = 0x5be0cd19;
}

void sha_256_write(struct Sha_256 *sha_256, const void *data, size_t len)
{
 sha_256->total_len += len;

 const uint8_t *p = (const uint8_t *)data;

 while (len > 0) {

  if (sha_256->space_left == 64 && len >= 64) {
   consume_chunk(sha_256->h, p);
   len -= 64;
   p += 64;
   continue;
  }

  const size_t consumed_len = len < sha_256->space_left ? len : sha_256->space_left;
  memcpy(sha_256->chunk_pos, p, consumed_len);
  sha_256->space_left -= consumed_len;
  len -= consumed_len;
  p += consumed_len;
  if (sha_256->space_left == 0) {
   consume_chunk(sha_256->h, sha_256->chunk);
   sha_256->chunk_pos = sha_256->chunk;
   sha_256->space_left = 64;
  } else {
   sha_256->chunk_pos += consumed_len;
  }
 }
}

uint8_t *sha_256_close(struct Sha_256 *sha_256)
{
 uint8_t *pos = sha_256->chunk_pos;
 size_t space_left = sha_256->space_left;
 uint32_t *const h = sha_256->h;

 *pos++ = 0x80;
 --space_left;

 if (space_left < 8) {
  memset(pos, 0x00, space_left);
  consume_chunk(h, sha_256->chunk);
  pos = sha_256->chunk;
  space_left = 64;
 }
 const size_t left = space_left - 8;
 memset(pos, 0x00, left);
 pos += left;
 uint64_t len = sha_256->total_len;
 pos[7] = (uint8_t)(len << 3);
 len >>= 5;
 int i;
 for (i = 6; i >= 0; --i) {
  pos[i] = (uint8_t)len;
  len >>= 8;
 }
 consume_chunk(h, sha_256->chunk);

 int j;
 uint8_t *const hash = sha_256->hash;
 for (i = 0, j = 0; i < 8; i++) {
  hash[j++] = (uint8_t)(h[i] >> 24);
  hash[j++] = (uint8_t)(h[i] >> 16);
  hash[j++] = (uint8_t)(h[i] >> 8);
  hash[j++] = (uint8_t)h[i];
 }
 return sha_256->hash;
}

void calc_sha_256(uint8_t hash[32], const void *input, size_t len)
{
 struct Sha_256 sha_256;
 sha_256_init(&sha_256, hash);
 sha_256_write(&sha_256, input, len);
 (void)sha_256_close(&sha_256);
}

void xor_buf(const BYTE in[], BYTE out[], size_t len)
{
 size_t idx;

 for (idx = 0; idx < len; idx++)
  out[idx] ^= in[idx];
}

int aes_encrypt_cbc(const BYTE in[], size_t in_len, BYTE out[], const WORD key[], int keysize, const BYTE iv[])
{
 BYTE buf_in[16], buf_out[16], iv_buf[16];
 int blocks, idx;

 if (in_len % 16 != 0)
  return(0);

 blocks = in_len / 16;

 memcpy(iv_buf, iv, 16);

 for (idx = 0; idx < blocks; idx++) {
  memcpy(buf_in, &in[idx * 16], 16);
  xor_buf(iv_buf, buf_in, 16);
  aes_encrypt(buf_in, buf_out, key, keysize);
  memcpy(&out[idx * 16], buf_out, 16);
  memcpy(iv_buf, buf_out, 16);
 }

 return(1);
}

int aes_encrypt_cbc_mac(const BYTE in[], size_t in_len, BYTE out[], const WORD key[], int keysize, const BYTE iv[])
{
 BYTE buf_in[16], buf_out[16], iv_buf[16];
 int blocks, idx;

 if (in_len % 16 != 0)
  return(0);

 blocks = in_len / 16;

 memcpy(iv_buf, iv, 16);

 for (idx = 0; idx < blocks; idx++) {
  memcpy(buf_in, &in[idx * 16], 16);
  xor_buf(iv_buf, buf_in, 16);
  aes_encrypt(buf_in, buf_out, key, keysize);
  memcpy(iv_buf, buf_out, 16);

 }

 memcpy(out, buf_out, 16);

 return(1);
}

int aes_decrypt_cbc(const BYTE in[], size_t in_len, BYTE out[], const WORD key[], int keysize, const BYTE iv[])
{
 BYTE buf_in[16], buf_out[16], iv_buf[16];
 int blocks, idx;

 if (in_len % 16 != 0)
  return(0);

 blocks = in_len / 16;

 memcpy(iv_buf, iv, 16);

 for (idx = 0; idx < blocks; idx++) {
  memcpy(buf_in, &in[idx * 16], 16);
  aes_decrypt(buf_in, buf_out, key, keysize);
  xor_buf(iv_buf, buf_out, 16);
  memcpy(&out[idx * 16], buf_out, 16);
  memcpy(iv_buf, buf_in, 16);
 }

 return(1);
}

void increment_iv(BYTE iv[], int counter_size)
{
 int idx;

 for (idx = 16 - 1; idx >= 16 - counter_size; idx--) {
  iv[idx]++;
  if (iv[idx] != 0 || idx == 16 - counter_size)
   break;
 }
}

void aes_encrypt_ctr(const BYTE in[], size_t in_len, BYTE out[], const WORD key[], int keysize, const BYTE iv[])
{
 size_t idx = 0, last_block_length;
 BYTE iv_buf[16], out_buf[16];

 if (in != out)
  memcpy(out, in, in_len);

 memcpy(iv_buf, iv, 16);
 last_block_length = in_len - 16;

 if (in_len > 16) {
  for (idx = 0; idx < last_block_length; idx += 16) {
   aes_encrypt(iv_buf, out_buf, key, keysize);
   xor_buf(out_buf, &out[idx], 16);
   increment_iv(iv_buf, 16);
  }
 }

 aes_encrypt(iv_buf, out_buf, key, keysize);
 xor_buf(out_buf, &out[idx], in_len - idx);
}

void aes_decrypt_ctr(const BYTE in[], size_t in_len, BYTE out[], const WORD key[], int keysize, const BYTE iv[])
{

 aes_encrypt_ctr(in, in_len, out, key, keysize, iv);
}

int aes_encrypt_ccm(const BYTE payload[], WORD payload_len, const BYTE assoc[], unsigned short assoc_len,
                    const BYTE nonce[], unsigned short nonce_len, BYTE out[], WORD *out_len,
                    WORD mac_len, const BYTE key_str[], int keysize)
{
 BYTE temp_iv[16], counter[16], mac[16], *buf;
 int end_of_buf, payload_len_store_size;
 WORD key[60];

 if (mac_len != 4 && mac_len != 6 && mac_len != 8 && mac_len != 10 &&
    mac_len != 12 && mac_len != 14 && mac_len != 16)
  return(0);

 if (nonce_len < 7 || nonce_len > 13)
  return(0);

 if (assoc_len > 32768 )
  return(0);

 buf = (BYTE*)malloc(payload_len + assoc_len + 48 );
 if (! buf)
  return(0);

 aes_key_setup(key_str, key, keysize);

 payload_len_store_size = 16 - 1 - nonce_len;
 ccm_prepare_first_format_blk(buf, assoc_len, payload_len, payload_len_store_size, mac_len, nonce, nonce_len);
 end_of_buf = 16;

 ccm_format_assoc_data(buf, &end_of_buf, assoc, assoc_len);

 ccm_format_payload_data(buf, &end_of_buf, payload, payload_len);

 ccm_prepare_first_ctr_blk(counter, nonce, nonce_len, payload_len_store_size);

 memset(temp_iv, 0, 16);
 aes_encrypt_cbc_mac(buf, end_of_buf, mac, key, keysize, temp_iv);

 memcpy(out, payload, payload_len);
 memcpy(&out[payload_len], mac, mac_len);

 memcpy(temp_iv, counter, 16);
 increment_iv(temp_iv, 16 - 1 - mac_len);
 aes_encrypt_ctr(out, payload_len, out, key, keysize, temp_iv);

 aes_encrypt_ctr(&out[payload_len], mac_len, &out[payload_len], key, keysize, counter);

 free(buf);
 *out_len = payload_len + mac_len;

 return(1);
}

int aes_decrypt_ccm(const BYTE ciphertext[], WORD ciphertext_len, const BYTE assoc[], unsigned short assoc_len,
                    const BYTE nonce[], unsigned short nonce_len, BYTE plaintext[], WORD *plaintext_len,
                    WORD mac_len, int *mac_auth, const BYTE key_str[], int keysize)
{
 BYTE temp_iv[16], counter[16], mac[16], mac_buf[16], *buf;
 int end_of_buf, plaintext_len_store_size;
 WORD key[60];

 if (ciphertext_len <= mac_len)
  return(0);

 buf = (BYTE*)malloc(assoc_len + ciphertext_len + 48);
 if (! buf)
  return(0);

 aes_key_setup(key_str, key, keysize);

 *plaintext_len = ciphertext_len - mac_len;
 plaintext_len_store_size = 16 - 1 - nonce_len;
 memcpy(plaintext, ciphertext, *plaintext_len);
 memcpy(mac, &ciphertext[*plaintext_len], mac_len);

 ccm_prepare_first_ctr_blk(counter, nonce, nonce_len, plaintext_len_store_size);

 memcpy(temp_iv, counter, 16);
 increment_iv(temp_iv, 16 - 1 - mac_len);
 aes_decrypt_ctr(plaintext, *plaintext_len, plaintext, key, keysize, temp_iv);

 if (mac_auth != 
                ((void *)0)
                    ) {

  aes_decrypt_ctr(mac, mac_len, mac, key, keysize, counter);

  plaintext_len_store_size = 16 - 1 - nonce_len;
  ccm_prepare_first_format_blk(buf, assoc_len, *plaintext_len, plaintext_len_store_size, mac_len, nonce, nonce_len);
  end_of_buf = 16;

  ccm_format_assoc_data(buf, &end_of_buf, assoc, assoc_len);

  ccm_format_payload_data(buf, &end_of_buf, plaintext, *plaintext_len);

  memset(temp_iv, 0, 16);
  aes_encrypt_cbc_mac(buf, end_of_buf, mac_buf, key, keysize, temp_iv);

  if (! memcmp(mac, mac_buf, mac_len)) {
   *mac_auth = 1;
  }
  else {
   *mac_auth = 0;
   memset(plaintext, 0, *plaintext_len);
  }
 }

 free(buf);

 return(1);
}

void ccm_format_assoc_data(BYTE buf[], int *end_of_buf, const BYTE assoc[], int assoc_len)
{
 int pad;

 buf[*end_of_buf + 1] = assoc_len & 0x00FF;
 buf[*end_of_buf] = (assoc_len >> 8) & 0x00FF;
 *end_of_buf += 2;
 memcpy(&buf[*end_of_buf], assoc, assoc_len);
 *end_of_buf += assoc_len;
 pad = 16 - (*end_of_buf % 16);
 memset(&buf[*end_of_buf], 0, pad);
 *end_of_buf += pad;
}

void ccm_format_payload_data(BYTE buf[], int *end_of_buf, const BYTE payload[], int payload_len)
{
 int pad;

 memcpy(&buf[*end_of_buf], payload, payload_len);
 *end_of_buf += payload_len;
 pad = *end_of_buf % 16;
 if (pad != 0)
  pad = 16 - pad;
 memset(&buf[*end_of_buf], 0, pad);
 *end_of_buf += pad;
}

void aes_key_setup(const BYTE key[], WORD w[], int keysize)
{
 int Nb=4,Nr,Nk,idx;
 WORD temp,Rcon[]={0x01000000,0x02000000,0x04000000,0x08000000,0x10000000,0x20000000,
                   0x40000000,0x80000000,0x1b000000,0x36000000,0x6c000000,0xd8000000,
                   0xab000000,0x4d000000,0x9a000000};

 switch (keysize) {
  case 128: Nr = 10; Nk = 4; break;
  case 192: Nr = 12; Nk = 6; break;
  case 256: Nr = 14; Nk = 8; break;
  default: return;
 }

 for (idx=0; idx < Nk; ++idx) {
  w[idx] = ((key[4 * idx]) << 24) | ((key[4 * idx + 1]) << 16) |
       ((key[4 * idx + 2]) << 8) | ((key[4 * idx + 3]));
 }

 for (idx = Nk; idx < Nb * (Nr+1); ++idx) {
  temp = w[idx - 1];
  if ((idx % Nk) == 0)
   temp = SubWord((((temp) << 8) | ((temp) >> 24))) ^ Rcon[(idx-1)/Nk];
  else if (Nk > 6 && (idx % Nk) == 4)
   temp = SubWord(temp);
  w[idx] = w[idx-Nk] ^ temp;
 }
}

